import { err, ok, type Result, withErrorContext } from './result.ts';
import {
	buildColorConstants,
	buildDurationConstants,
	buildLengthConstants,
	buildShadowConstants,
	buildTypographyConstants,
	type SwiftConstant,
} from './swift-sections.ts';
import { SWIFT_SUPPORT_TYPES } from './swift-support-types.ts';
import type { TokenFile } from './token-schema.ts';

type SwiftEnumSection = { name: string; constants: SwiftConstant[] };

const FILE_HEADER =
	'// Generated by tools/tokens from design/tokens.json. Do not edit; run `pnpm --filter @vaultday/tokens generate`.';

/**
 * Renders the complete `Tokens.swift` for a validated token file.
 * Fails with a message when a token value or name cannot be expressed in Swift.
 */
export function generateTokensSwift(tokenFile: TokenFile): Result<string> {
	const sections = buildSections(tokenFile);
	if (!sections.ok) return sections;
	const enums = sections.value.map(renderEnumSection).join('\n\n');
	return ok(
		[
			FILE_HEADER,
			'import AppKit',
			'import SwiftUI',
			'',
			'/// The Vaultday design tokens, light and dark.',
			'enum Tokens {',
			enums,
			'}',
			'',
			SWIFT_SUPPORT_TYPES,
		].join('\n'),
	);
}

function buildSections(tokenFile: TokenFile): Result<SwiftEnumSection[]> {
	const builders: [string, () => Result<SwiftConstant[]>][] = [
		['Colors', () => buildColorConstants(tokenFile.color.tokens)],
		[
			'Spacing',
			() => buildLengthConstants('spacing', tokenFile.spacing.tokens),
		],
		['Radius', () => buildLengthConstants('radius', tokenFile.radius.tokens)],
		['Size', () => buildLengthConstants('size', tokenFile.size.tokens)],
		['Typography', () => buildTypographyConstants(tokenFile.type)],
		['Shadows', () => buildShadowConstants(tokenFile.shadow.tokens)],
	];
	const motion = tokenFile.motion;
	if (motion !== undefined) {
		builders.push(['Motion', () => buildDurationConstants(motion.tokens)]);
	}
	const sections: SwiftEnumSection[] = [];
	for (const [name, build] of builders) {
		const constants = build();
		if (!constants.ok) return withErrorContext(name, constants);
		if (constants.value.length === 0) return err(`${name}: no tokens`);
		sections.push({ name, constants: constants.value });
	}
	return ok(sections);
}

function renderEnumSection(section: SwiftEnumSection): string {
	const lines = section.constants.flatMap(renderConstant);
	return [`\tenum ${section.name} {`, ...lines, '\t}'].join('\n');
}

function renderConstant(constant: SwiftConstant): string[] {
	const typeAnnotation =
		constant.typeAnnotation === undefined ? '' : `: ${constant.typeAnnotation}`;
	return [
		`\t\t/// ${constant.usage}`,
		`\t\tstatic let ${constant.identifier}${typeAnnotation} = ${constant.expression}`,
	];
}
